# ============================================================================
# M2a_reconstruct_traj.R
# Module 2: trajectory-specific IPD reconstruction and absolute risk for longitudinal trajectories (sustained-negative / clearance / persistent-positive / seroconversion)
# No cross-study pooled multistate model (trajectory definitions/origins/endpoints cannot be aligned); per-study trajectory CIR is given,
# and single-trajectory reporting eligibility is flagged by the M4 event stratum.
#
# Inputs (generated by M2prep.py):
#   data/meta/curves2.csv   kmid,curve,time,St
#   data/meta/nar2.csv      kmid,curve,time,nrisk
#   data/meta/traj_meta.csv kmid,study_id,author,year,scen_code,win,endp_code,curve,trajectory
#
# Outputs outputs/M2/:
#   M2_ipd_trajectory_reconstructed.csv         reconstructed IPD (kmid,curve,trajectory,time,status)
#   M2_trajectory_absolute_risk.csv     trajectory CIR at 12/24/36 months + SE + n/events + eligibility
#   M2_event_counts.csv     n/events/cens per trajectory + event stratum
# ============================================================================
suppressPackageStartupMessages({
  library(readr); library(dplyr); library(tidyr); library(purrr); library(survival)
})
bundle <- "data/meta"; out_dir <- "outputs/M2"
dir.create(out_dir, showWarnings = FALSE, recursive = TRUE)
cur  <- read_csv(file.path(bundle,"curves2.csv"),  show_col_types = FALSE)
nar  <- read_csv(file.path(bundle,"nar2.csv"),     show_col_types = FALSE)
meta <- read_csv(file.path(bundle,"traj_meta.csv"),show_col_types = FALSE)

guyot <- function(times, surv, nr_t, nr_v) {
  if (length(times) < 3 || length(nr_t) < 2) return(NULL)
  if (times[1] != 0) { times <- c(0,times); surv <- c(1,surv) }
  o <- order(times); times <- times[o]; surv <- cummin(surv[o]); surv <- pmin(pmax(surv,0),1)
  Sat <- function(t) surv[findInterval(t,times,all.inside=TRUE)]
  ev_t <- numeric(0); cen_t <- numeric(0)
  for (i in seq_len(length(nr_t)-1)) {
    lo <- nr_t[i]; hi <- nr_t[i+1]; nlo <- nr_v[i]; nhi <- nr_v[i+1]
    if (is.na(nlo) || nlo<=0) next
    if (is.na(nhi)) nhi <- 0
    Slo <- Sat(lo); Shi <- Sat(hi); if (Slo<=0) next
    net <- nlo - nhi
    if (net < 0) { d <- 0; cc <- 0 } else {
      d <- round(nlo*(1-Shi/Slo)); d <- max(0,min(d,net)); cc <- nlo-d-nhi
    }
    if (d>0)  ev_t  <- c(ev_t, seq(lo,hi,length.out=d+2)[-c(1,d+2)])
    if (cc>0) cen_t <- c(cen_t,seq(lo,hi,length.out=cc+2)[-c(1,cc+2)])
  }
  target_n <- nr_v[1]; assigned <- length(ev_t)+length(cen_t)
  if (!is.na(target_n) && assigned < target_n) {
    tlast <- max(nr_t); tmax <- max(times); if (tmax<=tlast) tmax <- tlast+1
    miss <- target_n-assigned
    if (miss>0) cen_t <- c(cen_t,seq(tlast,tmax,length.out=miss+2)[-c(1,miss+2)])
  }
  if (length(ev_t)+length(cen_t)==0) return(NULL)
  data.frame(time=c(ev_t,cen_t), status=c(rep(1L,length(ev_t)),rep(0L,length(cen_t))))
}

ipd_all <- list(); ec_all <- list(); ar_all <- list(); ii<-0; kk<-0
for (i in seq_len(nrow(meta))) {
  r <- meta[i,]
  cc <- cur %>% filter(kmid==r$kmid, curve==r$curve) %>% arrange(time)
  nn <- nar %>% filter(kmid==r$kmid, curve==r$curve) %>% arrange(time)
  if (nrow(cc)<3 || nrow(nn)<2) {
    kk<-kk+1; ec_all[[kk]]<-data.frame(kmid=r$kmid,curve=r$curve,trajectory=r$trajectory,
      n0=NA,events=NA,cens=NA,recon_N=NA,ev_layer="failed")
    next
  }
  ipd <- guyot(cc$time, cc$St, nn$time, nn$nrisk)
  if (is.null(ipd)) {
    kk<-kk+1; ec_all[[kk]]<-data.frame(kmid=r$kmid,curve=r$curve,trajectory=r$trajectory,
      n0=nn$nrisk[1],events=NA,cens=NA,recon_N=NA,ev_layer="failed"); next
  }
  ipd$kmid<-r$kmid; ipd$curve<-r$curve; ipd$trajectory<-r$trajectory
  ii<-ii+1; ipd_all[[ii]]<-ipd
  ev <- sum(ipd$status); n0 <- nn$nrisk[1]; tmax <- max(cc$time)
  layer <- case_when(ev<=10~"E1_le10", ev<=20~"E2_11to20", ev<=40~"E3_21to40", TRUE~"E4_gt40")
  kk<-kk+1; ec_all[[kk]]<-data.frame(kmid=r$kmid,curve=r$curve,trajectory=r$trajectory,
    n0=n0,events=ev,cens=sum(ipd$status==0),recon_N=nrow(ipd),tmax=round(tmax,1),ev_layer=layer)
  sf <- survfit(Surv(time,status)~1,data=ipd)
  for (tp in c(12,24,36)) {
    if (tp > tmax) next
    ss <- summary(sf, times=tp, extend=TRUE)
    se <- ss$std.err; cir <- 1-ss$surv
    se_cir <- se  # CIR=1-S, Greenwood SE same
    ar_all[[length(ar_all)+1]] <- data.frame(
      kmid=r$kmid,study_id=r$study_id,author=r$author,year=r$year,
      scen_code=r$scen_code,win=r$win,endp_code=r$endp_code,trajectory=r$trajectory,
      n0=n0,events=ev,ev_layer=layer,time=tp,
      CIR=cir,CIRlo=max(0,cir-1.96*se_cir),CIRhi=min(1,cir+1.96*se_cir))
  }
}
ipd_df <- bind_rows(ipd_all); ec <- bind_rows(ec_all); ar <- bind_rows(ar_all)
ar <- ar %>% mutate(
  single_report = case_when(ev_layer %in% c("E3_21to40","E4_gt40") ~ "single_trajectory_OK",
                            ev_layer=="E2_11to20" ~ "imprecise_wideCI",
                            TRUE ~ "direction_only"),
  trajectory=factor(trajectory,levels=c("sust_neg","clearance","emergent","persistent","ever_pos")))

cat("\n===== M2a recon summary =====\n")
cat("trajectories:",nrow(meta)," reconstructed:",nrow(ec %>% filter(ev_layer!='failed')),"\n")
cat("IPD persons:",nrow(ipd_df)," events:",sum(ec$events,na.rm=TRUE),"\n")
cat("\nevent layer by trajectory:\n"); print(table(ec$trajectory,ec$ev_layer,useNA="ifany"))
write_csv(ipd_df,file.path(out_dir,"M2_ipd_trajectory_reconstructed.csv"))
write_csv(ec,file.path(out_dir,"M2_event_counts.csv"))
write_csv(ar,file.path(out_dir,"M2_trajectory_absolute_risk.csv"))
cat("\nwritten outputs/M2: M2_ipd_trajectory_reconstructed.csv, M2_event_counts.csv, M2_trajectory_absolute_risk.csv\n")
